#!/usr/bin/env python3
"""Install isolated Git hook entrypoints without discarding existing hooks."""
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

FRAMEWORK_PREFIX = """#!/usr/bin/env bash
# File generated by pre-commit: https://pre-commit.com
# ID: 138fd403232d2ddd5efb44317e38bf03

# start templated
"""
FRAMEWORK_SUFFIX = """# end templated

HERE="$(cd "$(dirname "$0")" && pwd)"
ARGS+=(--hook-dir "$HERE" -- "$@")

if [ -x "$INSTALL_PYTHON" ]; then
    exec "$INSTALL_PYTHON" -mpre_commit "${ARGS[@]}"
elif command -v pre-commit > /dev/null; then
    exec pre-commit "${ARGS[@]}"
else
    echo '`pre-commit` not found.  Did you forget to activate your virtualenv?' 1>&2
    exit 1
fi
"""


def is_standard_framework_hook(content, hook_type):
    if not content.startswith(FRAMEWORK_PREFIX) or not content.endswith(FRAMEWORK_SUFFIX):
        return False
    middle = content[len(FRAMEWORK_PREFIX):-len(FRAMEWORK_SUFFIX)]
    pattern = r'INSTALL_PYTHON=[^\r\n]+\nARGS=\(hook-impl --config=\.pre-commit-config\.yaml --hook-type=' + re.escape(hook_type) + r'\)\n'
    return re.fullmatch(pattern, middle) is not None


def launcher_for(hook_type):
    return '''#!/usr/bin/env bash
# Capell isolated HOOK_TYPE hook v1
set -eu
root=$(git rev-parse --show-toplevel)
script="$root/scripts/hooks/HOOK_TYPE.py"
if [ ! -f "$script" ]; then
    echo 'Capell HOOK_TYPE: snapshot hook is missing in this checkout; update the branch before continuing.' >&2
    exit 1
fi
exec python3 "$script" "$@"
'''.replace('HOOK_TYPE', hook_type)


def git(*args):
    return subprocess.run(['git', *args], text=True, capture_output=True, check=True).stdout.strip()


def main():
    root = Path(git('rev-parse', '--show-toplevel')).resolve()
    common = Path(git('rev-parse', '--git-common-dir')).resolve()
    git_dir = Path(git('rev-parse', '--absolute-git-dir')).resolve()
    if common != git_dir:
        raise RuntimeError('Run this installer in the primary checkout; linked worktrees share its hooks.')
    configured = subprocess.run(['git', 'config', '--get', 'core.hooksPath'], capture_output=True, text=True)
    if configured.returncode not in (0, 1) or configured.stdout.strip():
        raise RuntimeError('A custom core.hooksPath is configured. Review and install the entrypoints there manually.')
    hook_dir = common / 'hooks'
    hook_dir.mkdir(exist_ok=True)
    plans = []
    for hook_type in ('pre-commit', 'pre-push'):
        if not (root / f'scripts/hooks/{hook_type}.py').is_file():
            raise RuntimeError(f'The {hook_type} snapshot hook source is missing in this checkout.')
        hook = hook_dir / hook_type
        legacy = hook_dir / (hook_type + '.legacy')
        backup = hook_dir / (hook_type + '.pre-commit-framework')
        if hook.is_symlink() or legacy.is_symlink() or backup.is_symlink():
            raise RuntimeError(f'An existing {hook_type} hook is a symlink; review it manually before installing.')
        existing = hook.read_text(errors='replace') if hook.exists() else ''
        framework = is_standard_framework_hook(existing, hook_type)
        launcher = launcher_for(hook_type)
        preserve = bool(existing and existing != launcher and not framework)
        if preserve and legacy.exists():
            raise RuntimeError(f'Both {hook_type} and {hook_type}.legacy exist; preserve and review both before installing.')
        if framework and backup.exists() and backup.read_bytes() != hook.read_bytes():
            raise RuntimeError(f'A different {hook_type} framework backup exists; review both hooks before installing.')
        plans.append((hook, legacy, backup, launcher, framework, preserve, hook.stat() if hook.exists() else None))
    for hook, legacy, backup, launcher, framework, preserve, original_stat in plans:
        with tempfile.NamedTemporaryFile(mode='w', dir=hook_dir, delete=False) as handle:
            handle.write(launcher)
            temporary = Path(handle.name)
        try:
            temporary.chmod(0o755)
            if framework and not backup.exists():
                os.link(hook, backup)
            if preserve:
                os.link(hook, legacy)
            current_stat = hook.stat() if hook.exists() else None
            identity = lambda stat: None if stat is None else (stat.st_dev, stat.st_ino, stat.st_size, stat.st_mtime_ns)
            if identity(current_stat) != identity(original_stat):
                raise RuntimeError(f'{hook.name} changed during installation; review it before retrying.')
            os.replace(temporary, hook)
        finally:
            temporary.unlink(missing_ok=True)
    print('Installed isolated pre-commit and pre-push hooks; existing legacy hooks are preserved.')
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except (OSError, RuntimeError, subprocess.CalledProcessError) as error:
        print(f'Cannot install Git hooks: {error}', file=sys.stderr)
        raise SystemExit(1)
